void Solver::bump_var(int var, double coeff) {
    const double ACT_OVERFLOW = 1e100;
    const double VARINC_LIMIT = 1e90;
    const double SCALE = 1e-100;

    // Rescale globally if var_inc is becoming too large (pre‑emptive scaling)
    if (var_inc > VARINC_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Update activity of the variable
    activity[var] += var_inc * coeff;

    // If this variable overflowed, rescale everything now
    if (activity[var] > ACT_OVERFLOW) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
